success.assertion:
for(const [missing,tiers]of[[5,0],[6,1],[13,2]]){const s=make({move:38355,index:1});let left=missing;for(const k of s.fighters[0].moves){const used=Math.min(left,s.fighters[0].pp[k]-(k===key(38355)?1:0));s.fighters[0].pp[k]-=used;left-=used;}assert.equal(left,0);turn(s,38355,20309);const event=s.fighters[0].soulState.score4895.ppRestoreEvents[0];assert.equal(event.restored,missing+1);assert.equal(event.tiers,tiers);for(const stat of['atk','def','spa','spd','spe','acc'])assert.equal(s.fighters[1].stages[stat],tiers?-tiers:0);}
const s=make({move:38355,index:1});for(let n=0;n<2;n++){s.fighters[0].pp[key(38355)]-=5;turn(s,38355,20309);assert.equal(s.fighters[1].stages.def,0);assert.equal(s.fighters[0].soulState.score4895.ppRestoreEvents[n].discardedRemainder,6);}assert.equal(s.fighters[0].soulState.score4895.ppRestoredTotal,12);
for(const mode of['weak-immune','restore-blocked']){const s=make({move:38355,index:1});s.fighters[0].pp[key(38355)]=1;if(mode==='weak-immune')timer(s,1,'免弱');else{timer(s,1,'机械领域',{fraction:.6});s.fighters[1].soulState.bedPartnerPP=true;}turn(s,38355,20309);assert.ok(Number.isFinite(s.fighters[1].hp));assert.equal(s.fighters[1].stages.def,0);assert.equal(s.fighters[0].soulState.score4895.ppRestoreEvents[0].restored,mode==='weak-immune'?7:0);}

